Action.Str:
// Paste this into a Tasker JavaScriptlet action. Tasker passes the resulting
// %widget_layout variable to the following Widget v2 action.
var widget_layout = (function () {
    var hongKongNow = new Date(Date.now() + 8 * 60 * 60 * 1000);
    var today = Date.UTC(
        hongKongNow.getUTCFullYear(),
        hongKongNow.getUTCMonth(),
        hongKongNow.getUTCDate()
    );
    var departure = Date.UTC(2026, 10, 22);
    var days = Math.round((departure - today) / (24 * 60 * 60 * 1000));

    var number = days > 0 ? String(days) : days === 0 ? "TODAY" : "✈";
    var caption = days > 1 ? "DAYS TO GO" : days === 1 ? "DAY TO GO" :
        days === 0 ? "YOUR ADVENTURE BEGINS" : "HOPE YOU ENJOYED THE TRIP";

    return JSON.stringify({
        type: "Column",
        fillMaxSize: true,
        padding: 18,
        cornerRadius: 24,
        backgroundColor: "#102D38",
        horizontalAlignment: "Start",
        verticalAlignment: "Center",
        task: "Hong Kong Countdown",
        children: [
            {
                type: "Row",
                fillMaxWidth: true,
                verticalAlignment: "Center",
                children: [
                    {
                        type: "Text",
                        text: "✈  BOARDING PASS",
                        color: "#FFC886",
                        textSize: 12,
                        bold: true
                    },
                    { type: "Spacer", isWeighted: true },
                    {
                        type: "Text",
                        text: "HKG",
                        color: "#FFFFFF",
                        textSize: 15,
                        bold: true
                    }
                ]
            },
            { type: "Spacer", height: 10 },
            {
                type: "Text",
                text: "HONG KONG",
                color: "#FFFFFF",
                textSize: 23,
                bold: true,
                maxLines: 1
            },
            {
                type: "Text",
                text: "YOUR NEXT ADVENTURE",
                color: "#9FC3C8",
                textSize: 10,
                maxLines: 1
            },
            { type: "Spacer", height: 9 },
            {
                type: "Row",
                fillMaxWidth: true,
                verticalAlignment: "Bottom",
                children: [
                    {
                        type: "Text",
                        text: number,
                        color: "#FFC886",
                        textSize: days > 0 ? 48 : 34,
                        bold: true,
                        maxLines: 1
                    },
                    { type: "Spacer", width: 10 },
                    {
                        type: "Text",
                        text: caption,
                        color: "#FFFFFF",
                        textSize: 11,
                        bold: true,
                        maxLines: 2
                    }
                ]
            },
            { type: "Spacer", height: 8 },
            {
                type: "Text",
                text: "- - - - - - - - - - - - - - - - - - - -",
                color: "#53727B",
                textSize: 10,
                maxLines: 1
            },
            {
                type: "Row",
                fillMaxWidth: true,
                children: [
                    {
                        type: "Text",
                        text: "DEPARTURE  ·  22 NOV 2026",
                        color: "#D7E7E8",
                        textSize: 10,
                        maxLines: 1
                    },
                    { type: "Spacer", isWeighted: true },
                    {
                        type: "Text",
                        text: "HK  ✦",
                        color: "#FFC886",
                        textSize: 10,
                        maxLines: 1
                    }
                ]
            }
        ]
    });
})();
